def get_plain_dict(value):
    return json.loads(json.dumps(value))


def get_case_insensitive_value(desc, key_name):
    key_by_lower = {key.lower(): key for key in desc.keys()}
    return desc[key_by_lower[key_name.lower()]]


def get_rotator_value(rotation, key_name):
    return float(get_case_insensitive_value(desc=rotation, key_name=key_name))


def get_location_xyz(location):
    return np.array([
        float(get_case_insensitive_value(desc=location, key_name="X")),
        float(get_case_insensitive_value(desc=location, key_name="Y")),
        float(get_case_insensitive_value(desc=location, key_name="Z")),
    ], dtype=np.float64)


def unreal_vector_to_rerun_world(vector):
    return UNREAL_TO_RERUN_WORLD_MATRIX @ np.asarray(vector, dtype=np.float64)


def unreal_location_to_rerun_world(location):
    return unreal_vector_to_rerun_world(vector=get_location_xyz(location=location)) * UNREAL_CENTIMETERS_TO_RERUN_METERS


def build_light_rotation(camera_rotation, command):
    light_rotation = get_plain_dict(camera_rotation)
    key_by_lower = {key.lower(): key for key in light_rotation.keys()}
    light_rotation[key_by_lower["yaw"]] += command.yaw_offset_degrees
    light_rotation[key_by_lower["pitch"]] += command.pitch_offset_degrees
    return light_rotation


def get_unreal_rotation_matrix(rotation):
    pitch = math.radians(get_rotator_value(rotation=rotation, key_name="Pitch"))
    yaw = math.radians(get_rotator_value(rotation=rotation, key_name="Yaw"))
    roll = math.radians(get_rotator_value(rotation=rotation, key_name="Roll"))

    cp = math.cos(pitch)
    sp = math.sin(pitch)
    cy = math.cos(yaw)
    sy = math.sin(yaw)
    cr = math.cos(roll)
    sr = math.sin(roll)

    forward = np.array([cp*cy, cp*sy, sp], dtype=np.float64)
    right = np.array([sr*sp*cy - cr*sy, sr*sp*sy + cr*cy, -sr*cp], dtype=np.float64)
    up = np.array([-(cr*sp*cy + sr*sy), cy*sr - cr*sp*sy, cr*cp], dtype=np.float64)
    return np.column_stack([forward, right, up])


def get_rerun_camera_matrix(rotation):
    unreal_matrix = get_unreal_rotation_matrix(rotation=rotation)
    right = unreal_matrix[:, 1]
    down = -unreal_matrix[:, 2]
    forward = unreal_matrix[:, 0]
    return UNREAL_TO_RERUN_WORLD_MATRIX @ np.column_stack([right, down, forward])


